/// The id of the type the data names `name`, `w:CT_TblCellMar/w:tblCellMar`.
#[must_use]
pub fn type_id(name: &str) -> Option<TypeId> {
    let index = SCHEMA_TYPES
        .binary_search_by(|row| row.name.cmp(name))
        .ok()?;
    TypeId::try_from(index).ok()
}
